function getGoldenPath() {
  return [
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["add-zinc"], afterMs: 350 },
    { type: 'wait', ms: 720, afterMs: 80 },
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["add-copper"], afterMs: 350 },
    { type: 'wait', ms: 900, afterMs: 80 },
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["finish-reaction"], afterMs: 300 },
  ];
}

function runVerifierStep(step) {
  const stepType = typeof step === 'string' ? step : step?.type;
  if (stepType === "add-zinc" || stepType === 'run-autoplay') {
    return addZinc('autoplay');
  }
  if (stepType === "add-copper") {
    return addCopper('autoplay');
  }
  if (stepType === "finish-reaction") {
    return finishReaction();
  }
  return false;
}

installCoursewareTestHarness({
  state,
  mapState() {
    const zincContained = objectContainedInReactionZone(zincSample, zincReactionZone, { present: state.zincAdded, radiusPadding: 0.04, yPadding: 0.02 });
    const copperContained = state.copperAdded
      ? (
        objectContainedInReactionZone(copperLeaf.anchors["interactionZone"], copperReactionZone, { present: true })
        && objectContainedInReactionZone(copperLeaf.anchors.sampleZone, copperReactionZone, { present: true })
      )
      : true;
    const bubbleContained = particlePoolContainedInReactionZone(bubbleField, zincReactionZone, { radiusPadding: 0.05, yPadding: 0.04 });
    return {
      phase: reaction.state.phase,
      activeStep: state.activeStep,
      zincAdded: state.zincAdded,
      copperAdded: state.copperAdded,
      reactionProgress: reaction.state.progress,
      zincJarReturnedHome: state.zincJarReturnedHome,
      zincSampleContainedInTube: zincContained,
      copperContainedInTube: copperContained,
      bubbleFieldContainedInTube: bubbleContained,
      comparisonState: getComparisonState(),
      runtimeInvariants: {
        zincSampleContainedInTube: zincContained,
        copperContainedInTube: copperContained,
        bubbleFieldContainedInTube: bubbleContained,
        zincJarReturnedHome: state.zincJarReturnedHome,
      },
      recipe: state.recipe,
      source: state.source,
    };
  },
  getVerifierMeta() {
    return {
      supportsGoldenPath: true,
      successPhase: "result",
      failureStatusText: 'Thả chưa đúng vị trí',
    };
  },
  getCapabilities() {
    return recipeCapabilities;
  },
  getStepContract() {
    return recipeStepContract;
  },
  getGoldenPath,
  getDragPath(sampleId = 'zinc_jar') {
    if (sampleId === 'copper_leaf') {
      return {
        type: 'drag',
        from: projectWorldToCanvas(copperLeaf.anchors["interactionZone"], camera, renderer),
        to: projectWorldToCanvas(copperTube.anchors["mouth"], camera, renderer),
        steps: 24,
        afterMs: 420,
      };
    }
    return {
      type: 'drag',
      from: projectWorldToCanvas(zincJar.anchors["gripAnchor"], camera, renderer),
      to: projectWorldToCanvas(zincTube.anchors["mouth"], camera, renderer),
      steps: 24,
      afterMs: 420,
    };
  },
  dragFromPageApi({ sampleId } = {}) {
    if (sampleId === 'copper_leaf') {
      return addCopper('page-api');
    }
    return addZinc('page-api');
  },
  runVerifierStep,
});

autoplayButton?.addEventListener('click', () => {
  if (reaction.state.phase !== 'idle' || state.zincAdded || guidedZincMotion.state.active || guidedCopperMotion.state.active) {
    return;
  }
  guidedZincMotion.start();
});
resetButton?.addEventListener('click', resetScene);

let previousTime = performance.now();
function animate(now = performance.now()) {
  const dt = Math.min(0.05, Math.max(0.001, (now - previousTime) / 1000));
  previousTime = now;
  dragController.update(dt);
  guidedZincMotion.update(dt);
  guidedCopperMotion.update(dt);
  reaction.update(dt, now * 0.001);
  if (reaction.state.phase !== 'reaction') {
    bubbleField.update(dt, now * 0.001);
  }
  renderStatus();
  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

resetScene();
requestAnimationFrame(animate);

